using Check=std::function<void(bool,const char*)>;
class TestHost final:public CFrameWnd {void PostNcDestroy()override{}};
class ActivationBlock {HHOOK hook_=nullptr;public:ActivationBlock(){hook_=SetWindowsHookEx(WH_CBT,[](int code,WPARAM wp,LPARAM lp)->LRESULT{return code==HCBT_ACTIVATE?1:CallNextHookEx(nullptr,code,wp,lp);},nullptr,GetCurrentThreadId());if(!hook_)throw std::runtime_error("Cannot isolate layout test");}~ActivationBlock(){UnhookWindowsHookEx(hook_);}};
std::shared_ptr<sct::core::Image> Pixels(int w,int h,BYTE color){auto image=std::make_shared<sct::core::Image>();image->Create(w,h);for(size_t i=0;i<image->pixels.size();i+=4){image->pixels[i]=color;image->pixels[i+1]=color;image->pixels[i+2]=color;}return image;}
sct::core::DocumentState Source(){auto state=sct::core::Document(*Pixels(16,16,99)).State();sct::core::Annotation a;a.tool=sct::core::Tool::Rectangle;a.rect={2,2,8,8};state.objects.push_back(a);return state;}
void Seal(std::vector<BYTE>& data){uint32_t crc=~0u;for(size_t i=0;i<data.size()-4;++i){crc^=data[i];for(int bit=0;bit<8;++bit)crc=(crc>>1)^(0xEDB88320u&static_cast<uint32_t>(-static_cast<int>(crc&1)));}crc=~crc;memcpy(data.data()+data.size()-4,&crc,4);}
void Core(Check check,const std::filesystem::path& dir){using namespace sct;using namespace sct::services;const auto source=Source();const auto original=source.base->pixels;std::vector<std::shared_ptr<const core::Image>> images={Pixels(40,20,10),Pixels(12,32,50),Pixels(30,12,120)};const std::vector<CString> labels={L"A",L"B",L"C"};core::composition::Indices selected;core::LayoutOptions options{2,3,5,7};auto arranged=core::ArrangePictures(source,images,labels,options,selected);
    check(arranged.base->width==60&&arranged.base->height==54&&selected==core::composition::Indices({1,2,3}),"grid layout expands right/down and returns all new Picture indices");check(arranged.objects[1].asset==images[0]&&arranged.objects[2].asset==images[1]&&arranged.objects[3].asset==images[2]&&arranged.objects[0].rect.left==2,"layout keeps original image assets and existing editable objects");check(arranged.objects[1].rect.left==5&&arranged.objects[1].rect.top==7&&arranged.objects[2].rect.left==48&&arranged.objects[3].rect.top==42,"unequal image dimensions use non-overlapping column widths and row heights");
    bool retained=true;for(int y=0;y<16;++y)retained=retained&&!memcmp(arranged.base->Row(y),source.base->Row(y),64);check(retained&&source.base->pixels==original&&arranged.base->Row(53)[59*4]==255,"canvas expansion keeps source RGBA and adds only white surrounding space");core::Document document;document.Reset(source);document.Commit(arranged);check(document.Undo()&&document.State().base==source.base&&document.State().objects.size()==1&&document.Redo()&&document.State().objects.size()==4,"batch insert and canvas expansion are one undo/redo transaction");
    options.columns=1;auto vertical=core::ArrangePictures(source,images,labels,options,selected);check(vertical.objects[2].rect.top==30&&vertical.objects[3].rect.top==65,"one-column mode produces a vertical original-size arrangement");options.columns=64;auto horizontal=core::ArrangePictures(source,images,labels,options,selected);check(horizontal.objects[3].rect.left==63&&horizontal.objects[3].rect.top==7,"columns above image count produce a horizontal arrangement");
    for(int kind=0;kind<7;++kind){auto invalid=options;auto inputs=images;auto names=labels;if(kind==0)invalid.columns=0;if(kind==1)invalid.gap=-1;if(kind==2)invalid.x=-1;if(kind==3)invalid.x=32768;if(kind==4)inputs[1].reset();if(kind==5)inputs.resize(65,images.front());if(kind==6)names.pop_back();auto preserved=selected;bool rejected=false;try{core::ArrangePictures(source,inputs,names,invalid,selected);}catch(const std::exception&){rejected=true;}check(rejected&&selected==preserved&&source.base->pixels==original&&source.objects.size()==1,"invalid/over-limit/empty batch is rejected without partial source or selection changes");}
    CString error;std::vector<CString> paths;for(size_t i=0;i<images.size();++i){CString name;name.Format(L"layout-%zu.png",i);CString path=(dir/name.GetString()).c_str();check(CaptureService::Save(*images[i],path,error),"synthetic layout input saved only in private evidence");paths.push_back(path);}options={2,3,5,7};auto loaded=services::LayoutImageFiles(source,paths,options,selected);check(loaded.objects.size()==4&&loaded.objects[2].asset->pixels==images[1]->pixels,"batch service decodes each file and retains exact original pixels");paths[1]=(dir/L"missing-layout.png").c_str();bool failed=false;const auto previous=selected;try{services::LayoutImageFiles(source,paths,options,selected);}catch(const std::exception&){failed=true;}check(failed&&selected==previous&&source.base->pixels==original,"one missing file cancels the batch without inserting earlier successful files");
    auto collage=services::LayoutDocuments({source,source},{L"Document A",L"Document B"},{2,10,0,0});check(collage.objects.size()==2&&collage.objects[0].tool==core::Tool::Picture&&collage.objects[1].rect.left==26&&source.objects.size()==1,"collage renders RAM snapshots into separate movable pictures without modifying originals");
    auto metadata=source;metadata.objects[0].label=L"測試 layer";metadata.objects[0].hidden=true;std::vector<BYTE> bytes;core::DocumentState decoded;check(EncodeProject(metadata,bytes,error)&&bytes[8]==8&&DecodeProject(bytes,decoded,error)&&decoded.objects[0].label==metadata.objects[0].label&&decoded.objects[0].hidden,"v8 project round trip retains bounded Unicode labels and hidden state");
    auto legacy=source;std::vector<BYTE> old;EncodeProject(legacy,old,error);old.erase(old.end()-24,old.end()-4);old.erase(old.end()-20,old.end()-12);old[8]=6;Seal(old);check(DecodeProject(old,decoded,error)&&decoded.objects[0].label.IsEmpty()&&!decoded.objects[0].hidden,"actual v6 payload with no new fields loads visible unnamed defaults");
    for(int kind=0;kind<3;++kind){auto invalid=metadata;if(kind==0)invalid.objects[0].label=CString(L'x',81);if(kind==1)invalid.objects[0].label=L"bad\nlabel";if(kind==2)invalid.objects[0].label=L"bad\tlabel";auto unchanged=bytes;check(!EncodeProject(invalid,unchanged,error)&&unchanged==bytes,"invalid object labels fail before replacing an encoded project");}
    auto corrupt=bytes;int32_t invalidHidden=2;memcpy(corrupt.data()+corrupt.size()-36,&invalidHidden,4);Seal(corrupt);const auto base=decoded.base;check(!DecodeProject(corrupt,decoded,error)&&decoded.base==base,"invalid hidden flag fails transactionally during project decode");
    corrupt=bytes;int32_t invalidLength=81;const size_t labelAt=corrupt.size()-40-static_cast<size_t>(metadata.objects[0].label.GetLength())*sizeof(wchar_t);memcpy(corrupt.data()+labelAt,&invalidLength,4);Seal(corrupt);check(!DecodeProject(corrupt,decoded,error)&&decoded.base==base,"reader rejects oversized label length before allocating its string");
}
